    // Выбираем случайное письмо
    const randomEmail = STARTER_DB[Math.floor(Math.random() * STARTER_DB.length)];

    // Логика перемешивания вариантов (как в detector.js)
    let processedOptions = [];
    let correctIndices = [];

    if (randomEmail.isPhishing) {
        let pool = [];
        // Собираем все варианты
        randomEmail.true_options.forEach(t => pool.push({ text: t, isCorrect: true }));
        randomEmail.false_options.forEach(f => pool.push({ text: f, isCorrect: false }));
        
        // 1. Перемешиваем общий пул
        pool.sort(() => Math.random() - 0.5);
        
        // 2. Выбираем случайное количество (5, 6 или 7)
        const targetCount = Math.floor(Math.random() * 3) + 5;
        let finalSelection = pool.slice(0, targetCount);
        
        // 3. Гарантия: если случайно обрезали все верные ответы, возвращаем один
        if (!finalSelection.some(item => item.isCorrect)) {
            const correctItem = pool.find(item => item.isCorrect);
            if (correctItem) finalSelection[0] = correctItem;
        }
        
        // 4. Еще раз мешаем
        finalSelection.sort(() => Math.random() - 0.5);

        // 5. Формируем итоговые массивы
        processedOptions = finalSelection.map(i => i.text);
        correctIndices = finalSelection
            .map((item, index) => item.isCorrect ? index : -1)
            .filter(i => i !== -1);
            
    } else {
        // Для легитимных писем
        processedOptions = ["Это подозрительно"];
        correctIndices = [];
    }

    // Сохраняем в память браузера
    localStorage.setItem('preloaded_email', JSON.stringify({
        content: randomEmail.content,
        analysis: randomEmail.analysis,
        isPhishing: randomEmail.isPhishing,
        options: processedOptions,
        correctIndices: correctIndices,
        platform: randomEmail.platform
    }));
